"""Source-guided SL challenge sets. All numerical results are recomputed."""
from common import *
import math,random
A=Author('sl','A');B=Author('sl','B')
ca=[];cb=[];da=[];db=[];pa=[];pb=[];KEY_POSITIONS={}
def M(author,n,title,code,stem,options,solution,doc,page,q,focus,figure=None):
    # A stable seeded shuffle balances keys without a repeating answer cycle.
    if author.set not in KEY_POSITIONS:
        positions=list(range(4))*6+[2]
        random.Random('Physics SL '+author.set+' challenge 2026').shuffle(positions)
        KEY_POSITIONS[author.set]=positions
    k=KEY_POSITIONS[author.set][n-1];ordered=list(options[1:])
    random.Random('Physics SL '+author.set+' question '+str(n)).shuffle(ordered)
    ordered.insert(k,options[0])
    return author.mcq(n,title,code,stem,ordered,'ABCD'[k],solution+f' Therefore choose {"ABCD"[k]}.',anchor(doc,page,q,focus),'New numerical data and a changed inference or linked modelling task; original wording and recomputed distractors.',figure)
def W(author,section,n,title,code,stem,parts,schemes,doc,page,q,focus,figure=None):
    return author.written(section,n,title,code,stem,parts,schemes,anchor(doc,page,q,focus),'Rebuilt context/data and part sequence with independently recomputed results and a new precise figure where useful.',figure)

