ca.append(M(A,4,'Collision energy audit','A.2','On a horizontal frictionless track, cart X ($2.0\\,\\mathrm{kg}$) moves right at $6.0\\,\\mathrm{m\\,s^{-1}}$ while cart Y ($1.0\\,\\mathrm{kg}$) moves left at $3.0\\,\\mathrm{m\\,s^{-1}}$. After a collision Y moves right at $5.0\\,\\mathrm{m\\,s^{-1}}$. How much total kinetic energy is dissipated?', ['$24\\,\\mathrm{J}$','$16\\,\\mathrm{J}$','$18\\,\\mathrm{J}$','$40.5\\,\\mathrm{J}$'],'Taking right positive, $2(6)+1(-3)=2v_X+1(5)$, so $v_X=2.0\\,\\mathrm{m\\,s^{-1}}$. Initial kinetic energy is $40.5\\,\\mathrm{J}$ and final is $16.5\\,\\mathrm{J}$, giving $24\\,\\mathrm{J}$ dissipated. Momentum needs signed velocities; kinetic energy needs squared speeds.','6.pdf',2,'4','Momentum conservation in a one-dimensional collision',svg(rect(100,100,130,55,'X: 2.0 kg')+arrow(110,75,230,75,'6.0 m/s')+rect(380,100,130,55,'Y: 1.0 kg')+arrow(510,75,390,75,'3.0 m/s')+line(65,160,550,160),600,200)))
