ca.append(M(A,6,'Work on a rough slope','A.3','A $2.0\\,\\mathrm{kg}$ sled starts from rest and slides $3.0\\,\\mathrm{m}$ down a slope at $30^\\circ$ to the horizontal. The constant friction force is $3.0\\,\\mathrm{N}$. Use $g=10\\,\\mathrm{m\\,s^{-2}}$. What is its final speed?', ['$4.6\\,\\mathrm{m\\,s^{-1}}$','$5.5\\,\\mathrm{m\\,s^{-1}}$','$6.2\\,\\mathrm{m\\,s^{-1}}$','$3.0\\,\\mathrm{m\\,s^{-1}}$'],'The vertical drop is $3\\sin30^\\circ=1.5\\,\\mathrm{m}$. The kinetic-energy gain is $mg(1.5)-F(3)=30-9=21\\,\\mathrm{J}$. Since $\\tfrac12 mv^2=21$, $v=\\sqrt{21}=4.58\\,\\mathrm{m\\,s^{-1}}$.','6.pdf',3,'6','Work against friction along the slope',svg(line(100,220,490,75)+line(100,220,490,220,True)+rect(300,100,75,40,'sled')+text(165,205,'30 degrees',14)+arrow(250,145,330,115,'friction',290,105),600,270)))
