ca.append(M(A,7,'Thermal equilibrium','B.1','An insulated container mixes $0.30\\,\\mathrm{kg}$ of liquid P at $10^\\circ\\mathrm{C}$ with $0.20\\,\\mathrm{kg}$ of liquid Q at $70^\\circ\\mathrm{C}$. The final temperature is $30^\\circ\\mathrm{C}$. Heat absorbed by the container is negligible. What is $c_P/c_Q$?', ['$4/3$','$3/4$','$2$','$1/2$'],'Energy conservation gives $0.30c_P(30-10)=0.20c_Q(70-30)$. Thus $c_P/c_Q=8/6=4/3$. The different masses as well as the temperature changes must be included.','6.pdf',3,'7','Specific heat capacities inferred from equilibrium'))
ca.append(M(A,8,'Albedo and emissivity','B.2','Surfaces X and Y have the same temperature. X receives $400\\,\\mathrm{W\\,m^{-2}}$, reflects $80\\,\\mathrm{W\\,m^{-2}}$ and emits $300\\,\\mathrm{W\\,m^{-2}}$ as infrared. Y receives $600\\,\\mathrm{W\\,m^{-2}}$, reflects $180\\,\\mathrm{W\\,m^{-2}}$ and emits $200\\,\\mathrm{W\\,m^{-2}}$. Which statement follows?', ['Y has the greater albedo and $\\varepsilon_X/\\varepsilon_Y=1.50$.','X has the greater albedo and $\\varepsilon_X/\\varepsilon_Y=1.50$.','Y has the greater albedo and $\\varepsilon_X/\\varepsilon_Y=2/3$.','X has the greater albedo and $\\varepsilon_X/\\varepsilon_Y=2/3$.'],'Albedo is reflected divided by incident intensity: $0.20$ for X and $0.30$ for Y. At equal temperature, emitted intensity is proportional to emissivity, so $\\varepsilon_X/\\varepsilon_Y=300/200=1.50$. These data need not describe thermal equilibrium.','6.pdf',4,'8','Separate definitions of albedo and emissivity'))
