ca.append(M(A,9,'A disturbed climate balance','B.2','A planet initially absorbs and emits $240\\,\\mathrm{W\\,m^{-2}}$ at the top of its atmosphere. An increase in infrared-absorbing gas initially reduces the outgoing intensity to $180\\,\\mathrm{W\\,m^{-2}}$, without changing absorbed sunlight. Which prediction is consistent with energy conservation?', ['The planet initially gains energy, and warming can restore outgoing intensity to $240\\,\\mathrm{W\\,m^{-2}}$.','The planet initially loses energy and cools until it emits $180\\,\\mathrm{W\\,m^{-2}}$.','The planet remains at the same temperature because incoming sunlight is unchanged.','The gas permanently removes $60\\,\\mathrm{W\\,m^{-2}}$ of energy from the universe.'],'Initially the gain is $240-180=60\\,\\mathrm{W\\,m^{-2}}$. Infrared absorption and re-emission redistribute energy; they do not destroy it. A higher planetary temperature can increase emission until the top-of-atmosphere balance is restored.','6.pdf',4,'9','Greenhouse absorption and re-emission',svg(arrow(160,35,160,210,'absorbed: 240 W/m2',160,25)+arrow(420,210,420,35,'outgoing: 180 W/m2',420,25)+line(70,220,530,220)+text(300,255,'planet and atmosphere',15,'middle'),600,280)))
