ca.append(M(A,10,'A pressure-sensor offset','B.3','An ideal gas occupies a rigid $0.050\\,\\mathrm{m^3}$ vessel. Its indicated pressure follows the plotted straight line. The pressure sensor has a constant zero error. Use $R=8.31\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}$. How many moles of gas are present?', ['$2.41\\,\\mathrm{mol}$','$0.00241\\,\\mathrm{mol}$','$3.61\\,\\mathrm{mol}$','$1.66\\,\\mathrm{mol}$'],'For true pressure, $P=nRT/V$. A constant offset changes the intercept but not the gradient. From the plotted points, $\\Delta P/\\Delta T=(180-100)/200=0.400\\,\\mathrm{kPa\\,K^{-1}}=400\\,\\mathrm{Pa\\,K^{-1}}$. Thus $n=(400)(0.050)/8.31=2.41\\,\\mathrm{mol}$.','6.pdf',5,'10','Pressure-temperature slope and gas volume',plot([(200,100),(400,180)],(0,450),(0,200),'absolute temperature / K','indicated pressure / kPa',(0,200,400),(0,100,180),labels=[((200,100),'(200, 100)',8,-12),((400,180),'(400, 180)',-115,-14)])))
ca.append(M(A,11,'Microscopic gas comparisons','B.3','Two monatomic ideal-gas samples have the same temperature. Sample X contains twice as many atoms as sample Y, and each X atom has one-fifth the mass of a Y atom. What are $U_X/U_Y$ and $v_{\\rm rms,X}/v_{\\rm rms,Y}$?', ['$2$ and $\\sqrt5$','$2$ and $5$','$1$ and $\\sqrt5$','$10$ and $1/\\sqrt5$'],'For a monatomic ideal gas $U=\\tfrac32Nk_BT$, so the energy ratio is $2$. Also $\\tfrac12m\\langle v^2\\rangle=\\tfrac32k_BT$, so the rms speed ratio is $\\sqrt{m_Y/m_X}=\\sqrt5$. Atom number does not set the rms speed at fixed temperature.','6.pdf',5,'11','Molecular mass, number and internal energy'))
