ca.append(M(A,23,'Background-corrected decay','E.3','A source has half-life $40\\,\\mathrm{s}$. A detector measures $116\\,\\mathrm{s^{-1}}$ at $t=0$ and $44\\,\\mathrm{s^{-1}}$ at $t=80\\,\\mathrm{s}$. Background is constant. What is the ratio of source count rate to background count rate at $t=120\\,\\mathrm{s}$?', ['$0.60$','$0.40$','$1.20$','$0.145$'],'Let background be $b$. Two half-lives give $44-b=(116-b)/4$, hence $b=20\\,\\mathrm{s^{-1}}$. After three half-lives the source contributes $(116-20)/8=12\\,\\mathrm{s^{-1}}$. The requested ratio is $12/20=0.60$, using source rather than gross rate.','6.pdf',11,'23','Infer background before using integer half-lives',plot([(0,116),(40,68),(80,44),(120,32)],(0,130),(0,130),'time / s','gross count rate / s-1',(0,40,80,120),(0,20,44,68,116))))
