ca.append(M(A,24,'Binding energy in fission','E.4','A uranium-235 nucleus captures one neutron and splits into nuclei with nucleon numbers $141$ and $92$, plus free neutrons. Binding energy per nucleon is $7.6\\,\\mathrm{MeV}$ for uranium, $8.4\\,\\mathrm{MeV}$ for the first fragment and $8.6\\,\\mathrm{MeV}$ for the second. Approximately how much energy is released?', ['$190\\,\\mathrm{MeV}$','$7.8\\,\\mathrm{MeV}$','$330\\,\\mathrm{MeV}$','$1980\\,\\mathrm{MeV}$'],'Free neutrons have zero nuclear binding energy. Total final binding is $141(8.4)+92(8.6)=1975.6\\,\\mathrm{MeV}$; initial binding is $235(7.6)=1786.0\\,\\mathrm{MeV}$. The increase, $189.6\\,\\mathrm{MeV}$, is released. Conservation also gives three free neutrons.','6.pdf',11,'24','Fission and total binding-energy accounting'))
