cb.append(M(B,1,'Equal time intervals in free fall','A.1','A package is released from a descending platform with initial downward speed $4.0\\,\\mathrm{m\\,s^{-1}}$. Air resistance is negligible; use $g=10\\,\\mathrm{m\\,s^{-2}}$. What is the ratio of the distance travelled during the third second to that during the first second?', ['$29/9$','$3$','$5$','$34/14$'],'The distance in the first second is $4(1)+\\tfrac12(10)(1)^2=9\\,\\mathrm{m}$. During $t=2$ to $3\\,\\mathrm{s}$ it is $[4(3)+5(3)^2]-[4(2)+5(2)^2]=29\\,\\mathrm{m}$. Equal velocity increments do not imply equal distances.','a.pdf',1,'1','Constant acceleration and successive distances'))
B.check('B2 impact angle',math.degrees(math.atan(math.sqrt(2*10*18)/12)),57.6884667626,1e-8)
cb.append(M(B,2,'Impact direction of a horizontal launch','A.1','A ball leaves a horizontal ledge at $12\\,\\mathrm{m\\,s^{-1}}$. The ground is $18\\,\\mathrm{m}$ below the ledge. Neglect drag and use $g=10\\,\\mathrm{m\\,s^{-2}}$. At what angle below the horizontal does it hit?', ['$58^\\circ$','$32^\\circ$','$45^\\circ$','$72^\\circ$'],'The vertical impact speed is $\\sqrt{2gh}=\\sqrt{360}=18.97\\,\\mathrm{m\\,s^{-1}}$. Horizontal speed remains $12\\,\\mathrm{m\\,s^{-1}}$. Thus $\\tan\\theta=18.97/12$, giving $57.7^\\circ$. The displacement angle is not the velocity angle.','a.pdf',1,'2','Horizontal projectile motion',svg(line(65,60,220,60)+line(220,60,220,230)+line(220,230,540,230)+circle(220,53,6)+arrow(240,53,340,53,'12 m/s')+text(150,160,'18 m',15)+arrow(440,160,485,230,'impact',520,160),600,270)))
B.check('B3 average force',3*((.5*2*6)+((6-2)/2)*4)/6,7)
cb.append(M(B,3,'Signed area and average force','A.2','The graph gives the acceleration of a $3.0\\,\\mathrm{kg}$ trolley. The segments are straight. What is the average resultant force over the first $6.0\\,\\mathrm{s}$?', ['$7.0\\,\\mathrm{N}$','$9.0\\,\\mathrm{N}$','$12\\,\\mathrm{N}$','$18\\,\\mathrm{N}$'],'The signed acceleration-time area is $\\tfrac12(2)(6)+\\tfrac12(6-2)(4)=14\\,\\mathrm{m\\,s^{-1}}$. Therefore $F_{\\rm av}=m\\Delta v/\\Delta t=3(14)/6=7.0\\,\\mathrm{N}$. The negative tail must be included with its sign.','a.pdf',1,'3','Average force from an acceleration-time graph',plot([(0,0),(2,6),(6,-2)],(0,6),(-2,6),'time / s','acceleration / m s-2',(0,2,4,6),(-2,0,2,4,6))))
B.check('B4 retained KE fraction',(.5*4*(.5**2))/(.5*1+.5*3),.25)
cb.append(M(B,4,'Unequal masses in an inelastic collision','A.2','Carts of masses $m$ and $3m$ approach one another on a frictionless line with equal speeds $v$. They stick together. What fraction of the original total kinetic energy remains as kinetic energy?', ['$1/4$','$1/2$','$3/4$','$0$'],"Taking the lighter cart's motion positive, initial momentum is $mv-3mv=-2mv$. The combined velocity is $-v/2$. Initial energy is $\\tfrac12mv^2+\\tfrac12(3m)v^2=2mv^2$, and final is $\\tfrac12(4m)(v/2)^2=\\tfrac12mv^2$. The fraction is $1/4$.",'a.pdf',2,'4','Momentum and energy in sticking collisions'))
B.check('B5 pump input',12*(10*5+.5*2**2)/.60,1040)
cb.append(M(B,5,'Pump energy with an outlet jet','A.3','A pump raises water at $12\\,\\mathrm{kg\\,s^{-1}}$ through $5.0\\,\\mathrm{m}$. Water enters nearly at rest and leaves at $2.0\\,\\mathrm{m\\,s^{-1}}$. The useful mechanical-energy gain is $60\\%$ of electrical input. Use $g=10\\,\\mathrm{m\\,s^{-2}}$. What input power is required?', ['$1.04\\,\\mathrm{kW}$','$0.624\\,\\mathrm{kW}$','$1.00\\,\\mathrm{kW}$','$0.374\\,\\mathrm{kW}$'],'Useful power is $\\dot m(gh+v^2/2)=12(50+2)=624\\,\\mathrm{W}$. Electrical input is $624/0.60=1040\\,\\mathrm{W}$. Both potential and kinetic energy gains count as useful output.','a.pdf',2,'5','Efficiency including kinetic-energy transport'))
B.check('B6 series conduction gain',(1+.25)/(.25+.25),2.5)
cb.append(M(B,6,'Conduction through rods in series','B.1','Two rods of the same material and length are joined end to end between fixed-temperature reservoirs. Their diameters are $d$ and $2d$. The thinner rod is replaced by another rod of diameter $2d$, keeping both lengths unchanged. Neglect losses and contact resistance. By what factor does the steady heat-transfer rate increase?', ['$2.5$','$2$','$4$','$1.6$'],'For each rod, thermal resistance is $L/(kA)$. If the thin rod has resistance $R$, the thick rod has $R/4$. Initial series resistance is $5R/4$, while final resistance is $R/2$. At fixed total temperature difference, the rate increases by $(5R/4)/(R/2)=2.5$.','a.pdf',3,'6','Thermal conduction and cross-sectional area',svg(rect(70,100,170,32,'diameter d')+rect(240,80,220,72,'diameter 2d')+text(55,60,'hot reservoir',14)+text(455,60,'cold reservoir',14)+text(150,195,'equal lengths; insulated sides',15)+arrow(150,235,420,235,'heat flow'),600,270)))
B.check('B7 total heat capacity',(100-60)/((14-6)/60),300);B.check('B7 specific heat',300/.2,1500);B.check('B7 heat loss',60-300*(6/60),30)
cb.append(M(B,7,'Separating heat loss from heat capacity','B.1',"At the same liquid temperature, a $60\\,\\mathrm{W}$ heater produces a warming rate of $6.0\\,\\mathrm{K\\,min^{-1}}$ and a $100\\,\\mathrm{W}$ heater produces $14\\,\\mathrm{K\\,min^{-1}}$. The liquid mass is $0.20\\,\\mathrm{kg}$; container heat capacity is negligible. Heat loss depends only on temperature. What is the liquid's specific heat capacity?", ['$1500\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$','$500\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$','$300\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$','$2140\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$'],"Subtract $P=mc\\dot T+H$ at the common temperature to cancel the same loss $H$: $40=(0.20)c(8/60)$. Thus $c=1500\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$. It is incorrect to assume all either heater's power warms the liquid.",'a.pdf',3,'7','Calorimetry with a non-negligible thermal loss'))
energyfig=svg(line(70,70,530,70)+line(70,235,530,235)+text(80,55,'space',15)+text(80,220,'surface',15)+arrow(130,25,130,235,'100',130,18)+arrow(195,70,195,25,'20',220,40)+arrow(265,235,265,25,'10',290,40)+arrow(360,105,360,235,'25',388,168)+arrow(455,105,455,25,'15',480,40)+text(380,92,'atmosphere',14)+text(300,275,'all arrow values in W/m2',14,'middle'),600,300)
cb.append(M(B,8,'An atmospheric energy budget','B.2','The model is in steady state. Incoming solar intensity is $100\\,\\mathrm{W\\,m^{-2}}$; the atmosphere reflects $20$ and the surface reflects $10$. The atmosphere absorbs no solar radiation. It emits infrared intensities $25$ downward and $15$ upward, all in $\\mathrm{W\\,m^{-2}}$. What infrared intensity must it absorb from the surface?', ['$40\\,\\mathrm{W\\,m^{-2}}$','$30\\,\\mathrm{W\\,m^{-2}}$','$70\\,\\mathrm{W\\,m^{-2}}$','$95\\,\\mathrm{W\\,m^{-2}}$'],'Apply the energy balance to the atmosphere itself: its only absorption is surface infrared, and it emits $25+15=40\\,\\mathrm{W\\,m^{-2}}$. The surface emits $70+25=95$, of which $55$ escapes directly and $40$ is absorbed. The whole system then loses $55+15=70$, matching absorbed sunlight.','a.pdf',4,'8','Choose the correct energy-budget boundary',energyfig))
B.check('B8 atmospheric absorption',25+15,40)
cb.append(M(B,9,'Gas pressure and molecular speed','B.3','A sealed sample of ideal gas expands to twice its original volume. Its pressure rises to $1.5$ times its original pressure. What is the ratio of final to initial rms molecular speed?', ['$\\sqrt3$','$3$','$\\sqrt{0.75}$','$1.5$'],'For fixed particle number, $T\\propto PV$, so $T_2/T_1=(1.5)(2)=3$. Since $v_{\\rm rms}\\propto\\sqrt T$, the speed ratio is $\\sqrt3$. The gas expansion alone does not imply cooling when energy is supplied.','a.pdf',4,'9','Kinetic theory and the ideal-gas equation'))
B.check('B10 final mixture temperature',(8000-.020*3.30e5)/(.100*4200),10/3,1e-10)
cb.append(M(B,10,'Melting followed by warming','B.1','An insulated mixture contains $20\\,\\mathrm g$ of ice and $80\\,\\mathrm g$ of water, both at $0^\\circ\\mathrm C$. It receives $8.00\\,\\mathrm{kJ}$. Use latent heat of fusion $3.30\\times10^5\\,\\mathrm{J\\,kg^{-1}}$ and water specific heat capacity $4200\\,\\mathrm{J\\,kg^{-1}\\,K^{-1}}$. What is the final temperature?', ['$3.33^\\circ\\mathrm C$','$0^\\circ\\mathrm C$','$19.0^\\circ\\mathrm C$','$4.17^\\circ\\mathrm C$'],'Melting the ice requires $0.020(3.30\\times10^5)=6600\\,\\mathrm J$. The remaining $1400\\,\\mathrm J$ warms all $0.100\\,\\mathrm{kg}$ of water. Hence $\\Delta T=1400/(0.100\\times4200)=3.33\\,\\mathrm K$. The mass to warm includes the melted ice.','a.pdf',5,'10','Latent heat and changes of internal energy'))
cb.append(M(B,11,'Opening a parallel branch','B.5','A cell of emf $18\\,\\mathrm V$ and internal resistance $2.0\\,\\Omega$ supplies a $4.0\\,\\Omega$ resistor in parallel with a $12\\,\\Omega$ resistor. The $12\\,\\Omega$ branch is opened. What happens to the terminal potential difference and the current in the $4.0\\,\\Omega$ resistor?', ['Both increase.','Both decrease.','Terminal potential difference increases; the $4.0\\,\\Omega$ current decreases.','Terminal potential difference decreases; the $4.0\\,\\Omega$ current increases.'],'Initially external resistance is $3.0\\,\\Omega$, cell current $3.6\\,\\mathrm A$, terminal voltage $10.8\\,\\mathrm V$ and $4\\,\\Omega$ current $2.7\\,\\mathrm A$. After opening, cell current is $18/6=3.0\\,\\mathrm A$, terminal voltage $12\\,\\mathrm V$ and branch current $3.0\\,\\mathrm A$. Reduced internal voltage loss raises both requested quantities.','a.pdf',5,'11','Resistor networks and current sharing'))
