cb.append(M(B,12,'SHM slope and a mass change','C.1','The acceleration-displacement graph is for a mass $m$ attached to an ideal spring. The spring is then used with mass $4m$. What is the new oscillation period?', ['$0.628\\,\\mathrm s$','$0.314\\,\\mathrm s$','$0.157\\,\\mathrm s$','$1.26\\,\\mathrm s$'],'The slope gives $\\omega^2=12/0.030=400\\,\\mathrm{s^{-2}}$, so the original period is $2\\pi/20=0.314\\,\\mathrm s$. For the same spring, $T\\propto\\sqrt m$; quadrupling mass doubles the period to $0.628\\,\\mathrm s$.','a.pdf',6,'12','Acceleration-displacement and period',plot([(-.03,12),(.03,-12)],(-.04,.04),(-15,15),'displacement / m','acceleration / m s-2',(-.03,0,.03),(-12,0,12))))
