cb.append(M(B,22,'Breaking a nucleus into lighter nuclei','E.4','In a binding-energy model, a nucleus with $56$ nucleons and binding energy per nucleon $8.8\\,\\mathrm{MeV}$ is separated into fourteen helium-4 nuclei, each with binding energy per nucleon $7.1\\,\\mathrm{MeV}$. Neglect kinetic energies. What net energy transfer is required?', ['$95.2\\,\\mathrm{MeV}$ supplied','$95.2\\,\\mathrm{MeV}$ released','$1.7\\,\\mathrm{MeV}$ supplied','$492.8\\,\\mathrm{MeV}$ released'],'Initial total binding is $56(8.8)=492.8\\,\\mathrm{MeV}$. Final binding is $14(4)(7.1)=397.6\\,\\mathrm{MeV}$. Decreasing binding by $95.2\\,\\mathrm{MeV}$ requires that energy to be supplied; greater binding corresponds to lower rest energy.','a.pdf',10,'22','Total binding energy and the sign of a reaction energy'))
cb.append(M(B,23,'Controlling a thermal reactor','E.4','A thermal-neutron fission reactor operates at constant power. Neutron-absorbing control rods are inserted farther while all other conditions initially remain unchanged. Which is the immediate cause of the reduction in power?', ['Fewer neutrons survive to cause further fissions.','The rods slow neutrons mainly by elastic collisions without absorbing them.','Each fission now releases less energy because the binding energies change.','The rods increase the mass of each uranium nucleus.'],'Control rods absorb neutrons, lowering the number available to continue the chain reaction and reducing the fission rate. Moderation mainly slows neutrons; it is a different role. The nuclear energy released per fission is not changed by rod position.','a.pdf',11,'23','Distinguish moderator and control-rod roles'))
hr=svg(line(90,35,90,240)+line(90,240,520,240)+text(300,285,'surface temperature (decreases to the right)',14,'middle')+text(95,20,'luminosity / solar luminosity',14)+circle(240,65,5)+text(260,70,'X: 10000',15)+circle(240,215,5)+text(260,220,'Y: 0.0100',15)+line(240,45,240,240,True)+text(240,260,'same temperature',13,'middle'),600,310)
