cb.append(M(B,25,'Parallax and apparent brightness','E.5','Stars X and Y have equal luminosity. Their parallax angles are $0.050$ and $0.200$ arc-seconds. Interstellar absorption is negligible. What is the ratio of observed brightness $b_X/b_Y$?', ['$1/16$','$1/4$','$4$','$16$'],'Distance is inversely proportional to parallax, so $d_X/d_Y=0.200/0.050=4$. Apparent brightness for equal luminosity follows $b\\propto1/d^2$, giving $b_X/b_Y=1/16$. Larger parallax means nearer and brighter in this comparison.','a.pdf',11,'25','Link annual parallax with inverse-square brightness'))

# Written and experimental questions follow.
tracepts=[]
for i in range(501):
    t=i/1000;tracepts.append((.18*t+.2*t*t,.012*math.cos(20*math.pi*t)))
trace=plot(tracepts,(0,.15),(-.016,.016),'longitudinal position / m','transverse pen displacement / m',(0,.04,.08,.12),(-.012,0,.012))
da.append(W(A,'1B',1,'An oscillating pen on an accelerating cart','A.1',r'A pen attached to a cart oscillates perpendicular to the direction of travel. Its calibrated frequency is $(10.0\pm0.2)\,\mathrm{Hz}$. The trace records successive positive peaks at the longitudinal positions below. Each position has maximum uncertainty $0.001\,\mathrm m$. Treat the frequency uncertainty as a maximum uncertainty and use a constant-acceleration model.\n\n| Peak number | 0 | 1 | 2 | 3 | 4 | 5 |\n|---|---|---|---|---|---|---|\n| Position / m | 0.000 | 0.020 | 0.044 | 0.072 | 0.104 | 0.140 |',[
('a',r'Calculate the time between successive peaks and its maximum uncertainty.',2),
('b',r'Estimate the longitudinal velocity at peak 2 using peaks 1 and 3.',2),
('c',r'Use the change in successive peak spacings to determine the acceleration.',2),
('d',r'Calculate the maximum uncertainty in your velocity estimate in (b).',2),
('e',r'A student says that increasing longitudinal peak spacings prove the pen frequency is increasing. Evaluate this claim.',2)], [
('a',[('M1',r'$T=1/f=0.100\,\mathrm s$.'),('A1',r'$\delta T/T=\delta f/f=0.020$, giving $\delta T=0.002\,\mathrm s$.')]),
('b',[('M1',r'Use the central interval: $v\approx(x_3-x_1)/(2T)$.'),('A1',r'$v=(0.072-0.020)/0.200=0.260\,\mathrm{m\,s^{-1}}$. For constant acceleration, this is the instantaneous velocity at the midpoint time.')]),
('c',[('M1',r'Successive spacings increase by $0.004\,\mathrm m$. With equal time intervals, $\Delta(\Delta x)=aT^2$.'),('A1',r'$a=0.004/(0.100)^2=0.400\,\mathrm{m\,s^{-2}}$.')]),
('d',[('M1',r'$\delta(\Delta x)=0.002\,\mathrm m$ and $\delta(2T)=0.004\,\mathrm s$. Add fractional maximum uncertainties: $\delta v/v=0.002/0.052+0.004/0.200$.'),('A1',r'$\delta v=0.0152\,\mathrm{m\,s^{-1}}$, so $v=(0.260\pm0.015)\,\mathrm{m\,s^{-1}}$; accept sensible uncertainty rounding such as $0.26\pm0.02$.')]),
('e',[('R1',r'The calibration gives a constant time between peaks; increasing spatial spacing can result from increasing cart speed.'),('R1',r'The trace alone does not demonstrate a frequency increase. A separate time calibration is needed; the constant-frequency accelerating-cart model is consistent with the data.')])], 'v.pdf',4,'2','Cart motion recorded by an oscillating pen',trace))
