db.append(W(B,'1B',1,'Conductivity with parasitic power loss','B.1',r'A laboratory measures the steady heater power $P$ needed to maintain a temperature difference $\Delta T=(30\pm1)\,\mathrm K$ across bars of one material. Each bar has area $A=(2.00\pm0.04)\times10^{-4}\,\mathrm{m^2}$. A constant parasitic power loss $P_0$ is proposed, so $P=kA\Delta T/L+P_0$.\n\n| Bar length $L$/m | 0.100 | 0.150 | 0.200 | 0.300 | 0.400 |\n|---|---|---|---|---|---|\n| Heater power $P$/W | 9.00 | 7.00 | 6.00 | 5.00 | 4.50 |\n\nA linear fit using a suitable horizontal-axis variable gives gradient $(0.600\pm0.030)\,\mathrm{W\,m}$.',[
('a',r'Choose a horizontal-axis quantity that linearizes the model. State the physical meanings of the gradient and vertical intercept.',2),
('b',r'Use the data to determine $P_0$, explaining why forcing the graph through the origin is inappropriate.',2),
('c',r'Calculate the thermal conductivity $k$.',2),
('d',r'Calculate the maximum percentage uncertainty in $k$, and state $k$ with an appropriate absolute uncertainty.',2),
('e',r'Give one physical reason the constant-$P_0$ model may fail for bars of different length and one practical improvement.',2)], [
('a',[('M1',r'Plot $P$ against $1/L$, measured in $\mathrm{m^{-1}}$.'),('A1',r'The gradient is $kA\Delta T$ and the vertical intercept is parasitic power $P_0$.')]),
('b',[('M1',r'For example, use $P_0=9.00-0.600(1/0.100)$.'),('A1',r'$P_0=3.00\,\mathrm W$. A nonzero loss exists even in the linearized model, so forcing zero intercept misassigns loss to conduction.')]),
('c',[('M1',r'$k=0.600/(2.00\times10^{-4}\times30)$.'),('A1',r'$k=100\,\mathrm{W\,m^{-1}\,K^{-1}}$.')]),
('d',[('M1',r'$\delta k/k=0.030/0.600+0.04/2.00+1/30=0.1033$.'),('A1',r'The maximum percentage uncertainty is about $10\%$, giving $k=(100\pm10)\,\mathrm{W\,m^{-1}\,K^{-1}}$.')]),
('e',[('R1',r'For example, longer bars may have more exposed surface and therefore different lateral heat loss; contact resistance may also differ between assemblies.'),('R1',r'Use effective insulation/guard heating to reduce lateral loss, or a controlled contact method to reduce variable contact resistance. The improvement must address the stated limitation.')])], 'q.pdf',3,'2','Steady conduction through a wall, reconstructed as a conductivity investigation',cond))
B.check('B1B conductivity',.6/(2e-4*30),100);B.check('B1B fractional uncertainty',.03/.6+.04/2+1/30,.103333333333,1e-10)

