# SL SET B PAPER 2.
pb.append(W(B,'2',1,'Settling spheres and model limits','A.2',r'A solid sphere of radius $1.00\,\mathrm{mm}$ and density $3000\,\mathrm{kg\,m^{-3}}$ falls through a stationary liquid of density $1000\,\mathrm{kg\,m^{-3}}$ and dynamic viscosity $0.200\,\mathrm{Pa\,s}$. Use $g=9.81\,\mathrm{m\,s^{-2}}$. For slow laminar motion, drag magnitude is $6\pi\eta rv$.',[
('a',r'Identify the three forces on the sphere and show that the net downward driving force, excluding drag, is $\tfrac43\pi r^3(\rho_s-\rho_l)g$.',3),('b',r'Calculate the terminal speed in this model.',2),('c',r'Predict the terminal-speed change if the radius is doubled while all other quantities remain fixed.',2),('d',r'State one reason your prediction in (c) might fail for a sufficiently large sphere.',1)], [
('a',[('R1',r'Weight acts down; buoyancy and motion-opposing viscous drag act up.'),('M1',r'Weight is $\tfrac43\pi r^3\rho_s g$ and buoyancy is the displaced-liquid weight $\tfrac43\pi r^3\rho_l g$.'),('A1',r'Subtracting yields $F_{\rm drive}=\tfrac43\pi r^3(\rho_s-\rho_l)g$.')]),
('b',[('M1',r'At terminal speed, $6\pi\eta rv_t=F_{\rm drive}$, so $v_t=2r^2(\rho_s-\rho_l)g/(9\eta)$.'),('A1',r'$v_t=0.0218\,\mathrm{m\,s^{-1}}$.')]),
('c',[('M1',r'With the other parameters fixed, the model gives $v_t\propto r^2$.'),('A1',r'Doubling radius makes the speed four times as large, $0.0872\,\mathrm{m\,s^{-1}}$.')]),
('d',[('R1',r'For example, flow may cease to be laminar so Stokes drag no longer applies, or the sphere may become too large for container-wall effects to be negligible. Accept a specific relevant limitation.')])], 's.pdf',1,'1','Buoyancy and viscous settling, changed to a radius-scaling and validity task',svg(rect(90,35,270,235)+circle(225,150,30)+arrow(225,182,225,250,'weight',300,235)+arrow(205,115,205,55,'buoyancy',130,60)+arrow(250,115,250,70,'drag',320,100)+text(470,160,'sphere falls down',15,'middle'),640,310)))
