# Normalize literal line breaks/apostrophes while preserving mathematical TeX.
def clean(value):
    if isinstance(value,str):return value.replace('\\n\\n','\n\n').replace('\\n|','\n|').replace("\\'", "'")
    if isinstance(value,list):return [clean(x) for x in value]
    if isinstance(value,dict):return {k:clean(v) for k,v in value.items()}
    return value
for author,choices,data,written in [(A,ca,da,pa),(B,cb,db,pb)]:
    paper('sl',author.set,'1',clean(choices+data));paper('sl',author.set,'2',clean(written));author.save_checks('sl-'+author.set.lower())
